      ProjectSchemaColumn: { type: "object", additionalProperties: false, required: ["name", "dataType", "nullable", "identity", "generated", "sensitive"], properties: { name: { type: "string" }, dataType: { type: "string" }, nullable: { type: "boolean" }, identity: { type: "boolean" }, generated: { type: "boolean" }, sensitive: { type: "boolean" } } },
